Object.assign(window.deepArticles, {
  "carolinian-navigation":micronesianInstitutionArticle({
    title:"Carolinian navigation",infoboxKicker:"Oceanic wayfinding tradition of the Caroline Islands",
    lead:"Carolinian navigation is the body of non-instrument oceanic knowledge used by navigators across the central and western Caroline Islands. It combines star courses, swells, winds, currents, birds, clouds, reefs, canoe behavior, island sequences, oral geography, and the moving-reference system known as <em>etak</em>. The tradition remains practical in 1985 as well as a major object of imperial preservation policy.",
    canon:"Carolinian navigation, star compasses, swell reading, etak, route recitation, restricted teaching, pwo initiation, named schools, and twentieth-century decline and revival are historical. Continued Japanese rule and preservation follow setting canon. Exact 1985 navigator numbers, licensing, school grants, military cooperation, and active routes remain open.",
    sections:[
      {id:"range",title:"Geographic range",html:"<p>Navigation schools historically connect Polowat, Pulap, Satawal, Lamotrek, Woleai, Ifalik, Ulithi, Yap, the Marianas, and more distant islands. Individual communities possess overlapping but nonidentical route systems.</p>"},
      {id:"stars",title:"Stars and direction",html:"<p>Named rising and setting stars define directional courses. Navigators hold a course while accounting for season, latitude, wind, current, vessel performance, and the changing visibility of celestial guides.</p>"},
      {id:"sea",title:"Swells and environmental signs",html:"<p>Primary and reflected swells, cloud forms, birds, fish, water color, drift, smell, reefs, and wave behavior provide evidence when stars are hidden or land remains below the horizon.</p>"},
      {id:"etak",title:"Etak positioning",html:"<p><a href='etak-navigation.html'>Etak</a> divides a voyage through imagined reference islands that move beneath successive stars while the canoe is treated as stationary. It organizes distance and progress within a relational mental geography.</p>"},
      {id:"teaching",title:"Teaching and initiation",html:"<p>Students learn through recitation, models, questioning, observation, canoe work, and supervised voyages. Advanced knowledge may be restricted until a teacher recognizes competence through <a href='pwo-navigation-initiation.html'>pwo initiation</a>.</p>"},
      {id:"colonial",title:"Colonial disruption",html:"<p>German and Japanese shipping, school schedules, wage labor, travel permits, motors, military restrictions, and imported navigation instruments reduced ordinary canoe voyaging. The knowledge survived most strongly in small central-Caroline communities.</p>"},
      {id:"revival",title:"Preservation and revival",html:"<p>Voyaging associations, canoe houses, recordings, school demonstrations, route archives, and long-distance expeditions renew public interest. Navigators retain authority over knowledge that should not be published without permission.</p>"},
      {id:"1985",title:"Status in 1985",html:"<p>By 1985 Carolinian navigation is endangered as an everyday transport system but vigorous as a recognized intellectual and ceremonial tradition. Some routes remain sailed for training, exchange, commemoration, and practical inter-island travel.</p>"}
    ],
    related:[{href:"etak-navigation.html",kicker:"Positioning system",label:"Etak Navigation"},{href:"pwo-navigation-initiation.html",kicker:"Navigator initiation",label:"Pwo"},{href:"micronesian-canoes.html",kicker:"Navigational vessel",label:"Canoes of Micronesia"},{href:"puluwatese-people.html",kicker:"Major navigation school",label:"Puluwatese People"},{href:"satawalese-people.html",kicker:"Major navigation community",label:"Satawalese People"},{href:"caroline-islands.html",kicker:"Regional geography",label:"Caroline Islands"}],
    facts:[["Region","Central and western Caroline Islands"],["Method","Non-instrument oceanic wayfinding"],["Principal directional framework","Star courses"],["Positioning concept","Etak"],["Environmental evidence","Swells, winds, birds, clouds, reefs, and currents"],["Specialist title","Palu or navigator"],["Initiation","Pwo"],["1985 condition","Endangered in daily use; active in preservation and training"]],
    sources:[{href:"https://nach.gov.fm/wp-content/uploads/2019/01/riesenberg-1972-the-organization-of-navigational-knowledge-on-puluwat-1.pdf",label:"FSM National Archives — organization of navigational knowledge on Puluwat"},{href:"https://micronesian.school/library/book/the-organization-of-navigational-knowledge-on-puluwat",label:"FSM Vernacular Language Arts Curriculum — navigation reference"}]
  }),
  "etak-navigation":micronesianInstitutionArticle({
    title:"Etak navigation",eyebrow:"Carolinian navigation · spatial knowledge",infoboxKicker:"Moving-reference positioning system",
    lead:"Etak is a Caroline-Island navigational system for tracking progress along an open-ocean route. The navigator treats the canoe as relatively stationary while a reference island, often invisible and off the actual course, moves through a sequence of star bearings. The method links direction, elapsed travel, swell, expected signs, and remembered geography without imitating a modern coordinate grid.",
    canon:"Etak's moving-reference principle, Caroline-Island distribution, relationship to star courses, named route segments, oral instruction, and role in navigator education are historical. Continued Japanese preservation follows setting canon. Exact terminology across languages, classified route lists, 1985 teaching protocols, and official curriculum remain open.",
    sections:[
      {id:"principle",title:"Moving-reference principle",html:"<p>In an etak account the canoe remains at the conceptual center while an off-course island is imagined to pass from one stellar bearing to another. The changing relationship measures progress toward the destination.</p>"},
      {id:"segments",title:"Voyage segments",html:"<p>A route is divided into named or understood segments associated with successive positions of the reference island. Segment length depends on the voyage, conditions, teaching lineage, and chosen reference.</p>"},
      {id:"stars",title:"Star compass relationship",html:"<p>Etak uses the directional framework supplied by rising and setting stars. It does not replace steering; it adds a mental measure of movement along the held course.</p>"},
      {id:"evidence",title:"Correction by observation",html:"<p>Swells, currents, birds, clouds, water color, drift, elapsed time, and vessel speed confirm or challenge the expected segment. A navigator revises judgment rather than applying a fixed mechanical formula.</p>"},
      {id:"islands",title:"Real and conceptual islands",html:"<p>Reference islands may be occupied, unoccupied, submerged, remembered from tradition, or never directly seen during the voyage. Their value lies in the navigational relationship, not in serving as physical checkpoints.</p>"},
      {id:"teaching",title:"Instruction",html:"<p>Teachers present etak through recitation, diagrams made from ordinary objects, questioning, and supervised sailing. Mastery requires the student to integrate the system with weather and canoe performance.</p>"},
      {id:"interpretation",title:"Modern interpretation",html:"<p>Japanese geographers compare etak with relative reference frames and dead reckoning, but no single technical analogy captures it. Preservationists reject portrayals of the system as mystical intuition without structured reasoning.</p>"},
      {id:"1985",title:"Etak in 1985",html:"<p>By 1985 etak is taught actively in a small number of navigation lineages and cultural programs. Some details remain restricted, and published descriptions do not constitute qualification to navigate.</p>"}
    ],
    related:[{href:"carolinian-navigation.html",kicker:"Parent tradition",label:"Carolinian Navigation"},{href:"pwo-navigation-initiation.html",kicker:"Qualification tradition",label:"Pwo"},{href:"puluwatese-language.html",kicker:"Technical vocabulary",label:"Puluwatese Language"},{href:"satawalese-language.html",kicker:"Related technical vocabulary",label:"Satawalese Language"},{href:"micronesian-canoes.html",kicker:"Operational platform",label:"Canoes of Micronesia"},{href:"caroline-islands.html",kicker:"Geographic setting",label:"Caroline Islands"}],
    facts:[["Type","Relative-position navigation concept"],["Region","Caroline Islands"],["Reference frame","Canoe treated as stationary"],["Moving element","Reference island"],["Directional framework","Rising and setting stars"],["Corrections","Swells, currents, time, weather, and vessel performance"],["Transmission","Oral instruction and supervised voyages"],["Instrument requirement","None"]],
    sources:[{href:"https://en.wikipedia.org/wiki/Etak_%28navigation%29",label:"Geographic reference — etak navigation"},{href:"https://nach.gov.fm/wp-content/uploads/2019/01/riesenberg-1972-the-organization-of-navigational-knowledge-on-puluwat-1.pdf",label:"FSM National Archives — Puluwat navigational organization"}]
  }),
  "pwo-navigation-initiation":micronesianInstitutionArticle({
    title:"Pwo",eyebrow:"Carolinian navigation · initiation",infoboxKicker:"Sacred initiation of navigators",
    lead:"Pwo is the sacred initiation through which a trained Caroline-Island navigator is recognized as a <em>palu</em> and admitted to advanced bodies of navigational knowledge. The rite joins technical competence, teacher lineage, ritual obligation, moral conduct, community service, and authority over restricted teaching. It is not a short course or honorary award detached from practical voyaging.",
    canon:"Pwo as navigator initiation, palu status, sacred and restricted knowledge, teacher lineages, ritual sequence, and modern revival are historical. Continued Japanese cultural policy follows setting canon. Exact 1985 initiates, ritual wording, officiants, public elements, and state recognition remain open.",
    sections:[
      {id:"purpose",title:"Purpose",html:"<p>Pwo confirms that a student has completed demanding instruction and accepts obligations attached to navigational authority. Recognition belongs to a lineage and community rather than to a metropolitan examining office.</p>"},
      {id:"preparation",title:"Preparation",html:"<p>Candidates study star courses, etak, swells, weather, islands, canoe handling, route narratives, and restricted names. Practical competence and conduct are assessed over years.</p>"},
      {id:"rite",title:"Initiation rite",html:"<p>The ceremony uses recitation, instruction, ritual objects, food, bodily discipline, and the authority of initiated navigators. Public descriptions preserve an outline but not every restricted act or formula.</p>"},
      {id:"palu",title:"The palu",html:"<p>An initiated navigator gains status as a <em>palu</em>, with authority to lead voyages and, under appropriate conditions, teach others. The title carries responsibility for passengers, crew, knowledge, and community reputation.</p>"},
      {id:"ethics",title:"Ethics and obligation",html:"<p>Technical skill alone is insufficient. Patience, judgment, restraint, generosity, truth about uncertainty, and duty to rescue or assist are part of navigational authority.</p>"},
      {id:"decline",title:"Colonial-era decline",html:"<p>Steamships, motors, mission criticism, schools, military travel controls, and fewer long canoe voyages reduced the number of candidates and teachers. Some lineages allowed rites to lapse.</p>"},
      {id:"revival",title:"Revival and public ceremony",html:"<p>Later initiations restore lineages and attract public attention. Cultural programs distinguish the visible celebration from knowledge that remains controlled by teachers and initiates.</p>"},
      {id:"1985",title:"Pwo in 1985",html:"<p>By 1985 pwo is rare but living. Japanese cultural agencies may fund vessels and documentation, but they cannot create a palu without recognition from qualified navigators.</p>"}
    ],
    related:[{href:"carolinian-navigation.html",kicker:"Technical tradition",label:"Carolinian Navigation"},{href:"etak-navigation.html",kicker:"Core navigational concept",label:"Etak Navigation"},{href:"puluwatese-people.html",kicker:"Navigation community",label:"Puluwatese People"},{href:"satawalese-people.html",kicker:"Navigation community",label:"Satawalese People"},{href:"micronesian-canoes.html",kicker:"Voyaging craft",label:"Canoes of Micronesia"},{href:"japanese-preservationism.html",kicker:"Preservation policy",label:"Japanese Preservationism"}],
    facts:[["Type","Sacred navigator initiation"],["Region","Central Caroline Islands"],["Recognized status","Palu · navigator"],["Prerequisite","Long technical and practical training"],["Knowledge","Star courses, etak, swells, weather, islands, and canoe handling"],["Authority","Qualified navigation lineages"],["Colonial-era condition","Severe decline"],["1985 condition","Rare but living"]],
    sources:[{href:"https://en.wikipedia.org/wiki/Pwo",label:"Cultural reference — pwo initiation"},{href:"https://nach.gov.fm/wp-content/uploads/2019/01/riesenberg-1972-the-organization-of-navigational-knowledge-on-puluwat-1.pdf",label:"FSM National Archives — navigator education"}]
  }),
  "sawei-system":micronesianInstitutionArticle({
    title:"Sawei",eyebrow:"Yap and the outer islands · exchange and hierarchy",infoboxKicker:"Traditional inter-island relationship system",
    lead:"Sawei was the hierarchical network linking districts of Yap with communities across the Yap outer islands. Outer-island partners sent tribute and valued products through established routes, while Yapese partners returned goods, political recognition, refuge, and protection. The system combined exchange, rank, ritual, navigation, and unequal power; neither the simple word “trade” nor “empire” describes it completely.",
    canon:"Sawei's Yap-centered hierarchy, Gagil connections, tribute routes, reciprocal gifts, refuge and protection claims, island ranking, and decline under colonial administration are historical. Its ceremonial afterlife under continued Japanese rule follows setting extrapolation. Exact 1985 observances, objects, route custodians, legal meaning, and political revival remain open.",
    sections:[
      {id:"range",title:"Geographic range",html:"<p>Sawei relationships extended eastward from Yap through Ulithi, Fais, Woleai, Lamotrek, Ifalik, and other islands. Not every community held the same rank or relationship.</p>"},
      {id:"yap",title:"Yapese partners",html:"<p>Communities associated especially with Gagil district received outer-island delegations and goods. Named partner relationships tied particular islands and estates together across generations.</p>"},
      {id:"tribute",title:"Tribute and gifts",html:"<p>Outer-island voyages carried woven goods, cordage, food, shell, craft products, and symbolic valuables. Yapese returns could include turmeric, stone money relationships, tools, food, status goods, and hospitality.</p>"},
      {id:"protection",title:"Protection and refuge",html:"<p>Sawei tradition promised refuge, assistance after disaster, and political protection. Its actual effectiveness varied, and hierarchy could expose outer islanders to demands and humiliation.</p>"},
      {id:"rank",title:"Island rank",html:"<p>The network mapped islands into an unequal moral geography. Rank influenced seating, speech, exchange, access, and labor without making outer-island peoples ethnically Yapese.</p>"},
      {id:"navigation",title:"Voyaging infrastructure",html:"<p>Sawei depended on canoes, route knowledge, hosts, seasonal timing, and inter-island news. Political order and navigational geography reinforced one another.</p>"},
      {id:"colonial",title:"Colonial transformation",html:"<p>German and Japanese government imposed district law, shipping, taxes, labor controls, and administrative offices that displaced the network's political functions. Ceremonial exchange and remembered partnerships survived.</p>"},
      {id:"1985",title:"Sawei in 1985",html:"<p>By 1985 sawei is not a parallel sovereign government. It persists through oral history, ceremonial exchange, route memory, Yap–outer-island relations, and political arguments over whether heritage language conceals earlier inequality.</p>"}
    ],
    related:[{href:"yapese-people.html",kicker:"Yapese center",label:"Yapese People"},{href:"ulithian-people.html",kicker:"Outer-island participant",label:"Ulithian People"},{href:"woleaian-people.html",kicker:"Outer-island participant",label:"Woleaian People"},{href:"ifalik-people.html",kicker:"Outer-island participant",label:"Ifalik People"},{href:"carolinian-navigation.html",kicker:"Voyaging infrastructure",label:"Carolinian Navigation"},{href:"indigenous-government-japanese-micronesia.html",kicker:"Political context",label:"Indigenous Government in Japanese Micronesia"}],
    facts:[["Type","Hierarchical inter-island relationship system"],["Center","Yap · especially Gagil relationships"],["Outer extent","Yap outer islands"],["Outward flow","Tribute, craft goods, food, and symbolic valuables"],["Return claims","Gifts, refuge, recognition, and protection"],["Infrastructure","Canoe routes and partner estates"],["Colonial effect","Political displacement and ceremonial survival"],["1985 status","Heritage network, not sovereign government"]],
    sources:[{href:"https://habeleinstitute.org/wiki/Sawei",label:"Habele Institute — sawei overview and bibliography"},{href:"https://www.tandfonline.com/doi/abs/10.1080/00223349208572704",label:"Journal of Pacific History — Yapese politics and sawei"},{href:"https://www.nepa.navy.mil/Portals/20/Documents/YapEIS/J-1.%20Airport%20Cultural%20Resources%20Survey%20Report_web.pdf?ver=I5NIf_hjLDHHqQrKmZPJBw%3D%3D",label:"Yap cultural-resources survey — sawei exchange system"}]
  }),
  "woleai-script":micronesianInstitutionArticle({
    title:"Woleai script",category:"Writing systems",eyebrow:"Caroline Islands · indigenous writing",infoboxKicker:"Historical syllabary of the Woleaian language",
    lead:"The Woleai script, also called the Caroline Islands script, is an indigenous syllabary developed on Woleai and neighboring islands in the early twentieth century. Its known inventory contains roughly ninety-eight or ninety-nine signs, including forms influenced by Latin letters. By 1985 it is a heritage script rather than the ordinary writing system of Woleaian.",
    canon:"The script's Woleai origin, early-twentieth-century documentation, syllabic character, partial Latin influence, debated prehistory, approximately 98–99 signs, incomplete phonological representation, and historical decline are established. Continued Japanese-era preservation follows setting extrapolation. Exact 1985 readers, curriculum, archive holdings, and revived standard remain open.",
    sections:[
      {id:"names",title:"Names and distribution",html:"<p>Woleai script emphasizes its language and island origin, while Caroline Islands script reflects early foreign descriptions. Knowledge extended across several Woleaian-speaking outer islands.</p>"},
      {id:"origin",title:"Contested origin",html:"<p>The script emerged after contact with Latin writing, but scholars disagree over whether an older local sign system was expanded or a new syllabary was created through stimulus diffusion. The surviving evidence does not settle the question completely.</p>"},
      {id:"structure",title:"Structure",html:"<p>Most signs represent consonant–vowel syllables, with additional forms for vowels and other values. The known inventory is not perfectly sufficient for every contrast in spoken Woleaian.</p>"},
      {id:"latin",title:"Latin-derived signs",html:"<p>A minority of glyphs visibly resemble Latin letters, while others have no simple alphabetic source. Local users altered values and added signs rather than merely copying a foreign alphabet.</p>"},
      {id:"use",title:"Historical use",html:"<p>Writers used the syllabary for names, messages, lists, records, and remembered texts. Knowledge varied by island and individual and never became a complete colonial administrative system.</p>"},
      {id:"decline",title:"Decline",html:"<p>Japanese schooling favored Japanese scripts, while missions and later linguistics favored Latin orthography. Limited teaching and the script's imperfect representation of length reduced everyday use.</p>"},
      {id:"preservation",title:"Documentation",html:"<p>German expedition records, island consultants, Japanese collections, later fieldwork, facsimiles, sign inventories, and digital encoding proposals preserve the script. Provenance remains important because forms differ among sources.</p>"},
      {id:"1985",title:"Status in 1985",html:"<p>By 1985 the Woleai script is historical but not forgotten. Cultural schools teach selected signs and history, while Latin spelling remains the normal way to write Woleaian.</p>"}
    ],
    related:[{href:"woleaian-language.html",kicker:"Language written",label:"Woleaian Language"},{href:"woleaian-people.html",kicker:"Originating community",label:"Woleaian People"},{href:"ifalik-language.html",kicker:"Regional variety",label:"Ifalik Language"},{href:"lamotrekese-language.html",kicker:"Regional variety",label:"Lamotrekese Language"},{href:"education-japanese-micronesia.html",kicker:"Competing school scripts",label:"Education in Japanese Micronesia"},{href:"japanese-preservationism.html",kicker:"Heritage policy",label:"Japanese Preservationism"}],
    facts:[["Alternative name","Caroline Islands script"],["Type","Syllabary"],["Language","Woleaian"],["Origin","Early twentieth century · Woleai region"],["Known inventory","Approximately 98–99 signs"],["Foreign influence","Partial Latin-letter stimulus"],["Ordinary 1985 script","Latin alphabet"],["1985 condition","Historical heritage script"]],
    sources:[{href:"https://repository.si.edu/bitstream/handle/10088/22111/bae_bulletin_173_1960_60_269-333.pdf",label:"Smithsonian Institution — The Woleai Script"},{href:"https://www.scriptsource.org/scr/Wole",label:"ScriptSource — Woleai script structure and history"},{href:"https://academic.oup.com/book/58672/chapter/485387962",label:"Oxford Academic — Caroline Islands script and writing-system debates"}]
  }),
  "micronesian-canoes":micronesianInstitutionArticle({
    title:"Canoes of Japanese Micronesia",eyebrow:"Maritime technology · Japanese Micronesia",infoboxKicker:"Indigenous sailing and paddling craft",
    lead:"The canoes of Japanese Micronesia comprise diverse outrigger sailing, paddling, fishing, lagoon, and voyaging craft built across the Marianas, Palau, Yap, the Carolines, and the Marshalls. Hull form, outrigger geometry, sail, steering, materials, decoration, ownership, and ritual differ by island. Canoes are technological systems embedded in land, kinship, navigation, and exchange rather than interchangeable symbols of a generic Pacific culture.",
    canon:"Regional outrigger traditions, local variation, tree and material rights, cooperative construction, navigation, colonial decline, motor competition, and revival are historical. Continued Japanese rule and preservation follow setting canon. Exact 1985 fleet, vessel classes, registration law, builders, routes, and subsidies remain open.",
    sections:[
      {id:"diversity",title:"Regional diversity",html:"<p>Chamorro, Palauan, Yapese, Chuukic, Pohnpeian, Kosraean, Marshallese, and Polynesian-outlier builders developed different craft for reefs, lagoons, open crossings, fishing, freight, and speed.</p>"},
      {id:"construction",title:"Construction",html:"<p>Builders select and shape hull timber, fit outrigger booms and float, lash components, prepare sail and rigging, and balance the vessel. Metal tools change production without eliminating inherited design knowledge.</p>"},
      {id:"rights",title:"Materials and ownership",html:"<p>Rights to trees, cordage plants, work, designs, canoe houses, beaches, and fishing grounds determine who can build and use a vessel. Construction mobilizes family and community obligations.</p>"},
      {id:"sailing",title:"Sailing and handling",html:"<p>Many voyaging canoes reverse direction by shifting the sail and steering end rather than tacking like a conventional European vessel. Crew weight, outrigger position, reefing, and wave approach require practiced coordination.</p>"},
      {id:"navigation",title:"Canoes and navigation",html:"<p>Vessel speed, leeway, loading, motion, and endurance form part of <a href='carolinian-navigation.html'>navigational judgment</a>. Route knowledge cannot be separated from knowledge of the craft actually sailed.</p>"},
      {id:"colonial",title:"Steamship and motor competition",html:"<p>Colonial steamers, Japanese subsidized routes, harbor rules, motors, wage schedules, and travel permits reduce long-distance canoe traffic. Motorboats later replace many fishing and administrative journeys.</p>"},
      {id:"revival",title:"Revival building",html:"<p>Canoe houses, apprenticeships, races, commemorative voyages, school projects, and cultural associations restore building knowledge. Revival vessels may use modern cordage or safety equipment while preserving hull and sailing principles.</p>"},
      {id:"1985",title:"Canoes in 1985",html:"<p>By 1985 small paddling and fishing craft remain ordinary in many islands, while major voyaging canoes are uncommon and culturally prestigious. Builders and navigators are recognized as technical specialists.</p>"}
    ],
    related:[{href:"carolinian-navigation.html",kicker:"Wayfinding tradition",label:"Carolinian Navigation"},{href:"pwo-navigation-initiation.html",kicker:"Navigator qualification",label:"Pwo"},{href:"marshallese-people.html",kicker:"Eastern canoe tradition",label:"Marshallese People"},{href:"yapese-people.html",kicker:"Western canoe tradition",label:"Yapese People"},{href:"puluwatese-people.html",kicker:"Central-Caroline builders",label:"Puluwatese People"},{href:"micronesian-peoples.html",kicker:"Regional communities",label:"Micronesian Peoples"}],
    facts:[["Primary form","Outrigger canoe"],["Uses","Fishing, lagoon travel, freight, racing, and ocean voyaging"],["Materials","Local timber, fiber lashings, sail material, and later manufactured fittings"],["Construction basis","Specialist design and cooperative labor"],["Operational knowledge","Sailing, reefs, weather, loading, and navigation"],["Colonial competitors","Steamships and motorboats"],["Major revival tools","Canoe houses, apprenticeships, races, and voyages"],["1985 condition","Small craft common; voyaging craft uncommon"]],
    sources:[{href:"https://www.researchgate.net/publication/321965019_Sailing_canoe_building_on_Mwoakilloa_Atoll",label:"Ethnographic reference — canoe building on Mwoakilloa"},{href:"https://nach.gov.fm/wp-content/uploads/2019/01/riesenberg-1972-the-organization-of-navigational-knowledge-on-puluwat-1.pdf",label:"FSM National Archives — vessels and navigation"}]
  }),
  "land-tenure-japanese-micronesia":micronesianInstitutionArticle({
    title:"Land tenure in Japanese Micronesia",eyebrow:"Property and customary law · Japanese Micronesia",infoboxKicker:"Island land and reef systems under Japanese rule",
    lead:"Land tenure in Japanese Micronesia consists of diverse customary systems governing house sites, gardens, tree crops, reefs, fishing grounds, chiefly shares, lineage rights, adoption, residence, and inheritance. German and Japanese surveys introduced registered parcels, government reserves, concessions, military zones, and company estates without fully replacing indigenous claims.",
    canon:"Matrilineal and other customary tenure, chiefly and lineage rights, colonial surveys, government land, concessions, settler acquisition, company estates, military reservations, and persistent disputes are historical. Continued Japanese sovereignty and citizenship follow setting canon. Uniform 1985 land code, adjudication, restitution, and island-specific shares remain open.",
    sections:[
      {id:"diversity",title:"Diverse customary systems",html:"<p>No single Micronesian tenure system exists. Palauan clans, Yapese estates, Chuukese lineages, Pohnpeian titles, Marshallese land roles, Chamorro family land, and outer-atoll rights follow different rules.</p>"},
      {id:"resources",title:"Land and marine rights",html:"<p>Tenure may distinguish soil, trees, crops, houses, wells, beaches, reef passages, fishing grounds, and harvest shares. One location can carry several overlapping rights and obligations.</p>"},
      {id:"descent",title:"Descent, adoption, and residence",html:"<p>Matrilineal descent is important across much of the region, but adoption, marriage, service, residence, chiefly grants, and individual transactions complicate any simple inheritance rule.</p>"},
      {id:"survey",title:"Colonial survey and registration",html:"<p>German and Japanese officials map boundaries, record owners, collect taxes, and identify government land. Written title can clarify claims while freezing flexible arrangements or privileging the person who spoke to the surveyor.</p>"},
      {id:"companies",title:"Companies and settlers",html:"<p>Sugar estates, phosphate mines, urban expansion, commercial farms, ports, and settler housing acquire or lease land. Unequal bargaining and compulsory powers make legality an incomplete measure of consent.</p>"},
      {id:"military",title:"Military reservations",html:"<p>Airfields, naval bases, radio stations, depots, and coastal defenses remove land and restrict reefs. Continued Japanese victory makes temporary wartime occupation a long-term property question.</p>"},
      {id:"courts",title:"Adjudication",html:"<p>Village leaders, district offices, survey bureaus, civil courts, and special commissions all hear disputes. Cases often turn on whether customary authority or registered title controls a particular right.</p>"},
      {id:"1985",title:"Land politics in 1985",html:"<p>By 1985 land remains the most durable source of conflict between indigenous communities, settlers, companies, and the state. Japanese nationality grants access to courts but does not erase unequal historical acquisition.</p>"}
    ],
    related:[{href:"japanese-settlement-micronesia.html",kicker:"Settler pressure",label:"Japanese Settlement in Micronesia"},{href:"sugar-industry-japanese-marianas.html",kicker:"Plantation acquisition",label:"Mariana Sugar Industry"},{href:"phosphate-mining-japanese-micronesia.html",kicker:"Mining concessions",label:"Micronesian Phosphate Mining"},{href:"indigenous-government-japanese-micronesia.html",kicker:"Customary authority",label:"Indigenous Government in Japanese Micronesia"},{href:"palauan-people.html",kicker:"Clan-land case",label:"Palauan People"},{href:"marshallese-people.html",kicker:"Atoll-land case",label:"Marshallese People"}],
    facts:[["Scope","Land, trees, houses, wells, reefs, fishing grounds, and harvest rights"],["Customary holders","Families, clans, lineages, chiefs, titleholders, and workers"],["Colonial instruments","Survey, registration, lease, concession, reserve, and expropriation"],["Major settler pressure","Marianas and Koror"],["Major company systems","Sugar and phosphate"],["Military burden","Airfields, naval bases, depots, and restricted reefs"],["1985 legal forum","Customary authorities, district offices, and Japanese courts"],["Uniform island-wide code","None"]],
    sources:[{href:"https://www.palaugov.pw/who-we-are/",label:"Palauan government reference — clans, land, and colonial history"},{href:"https://www.rmiembassyus.org/country-profile",label:"Marshall Islands reference — matrilineal land roles"},{href:"https://www.spf.org/islandstudies/global-data/a00023.pdf",label:"Ocean Policy Research Institute — Japanese mandatory rule"}]
  }),
  "christianity-japanese-micronesia":micronesianInstitutionArticle({
    title:"Christianity in Japanese Micronesia",eyebrow:"Religion · Japanese Micronesia",infoboxKicker:"Catholic and Protestant island churches",
    lead:"Christianity in Japanese Micronesia comprises Catholic and Protestant traditions established under Spanish, German, American-mission, and local leadership before or during early Japanese rule. Japan supervised missions and at times used churches as instruments of order, but did not eliminate island Christianity. By 1985 churches are among the strongest indigenous institutions across the region.",
    canon:"Spanish Catholic missionization in the Marianas and Palau, Protestant missions in the eastern Carolines and Marshalls, German-era churches, Japanese supervision and accommodation, local clergy, island literacy, and strong postwar continuity are historical or conservative setting consequences. Exact 1985 denominations, bishops, congregations, property, and state agreements remain open.",
    sections:[
      {id:"origins",title:"Mission origins",html:"<p>Catholic missions took deepest root in the Marianas and parts of the western islands. Protestant missions became especially influential in Kosrae, Ponape, the Marshalls, and neighboring atolls.</p>"},
      {id:"local",title:"Local congregations",html:"<p>Island pastors, catechists, teachers, choirs, women's groups, elders, and families turned imported religions into local institutions. Churches organize worship, welfare, education, funerals, music, and migration networks.</p>"},
      {id:"jurisdiction",title:"Jurisdiction, mission, and local church",html:"<!-- altwwii-writer-block:start id=wb-c-20260816-h3n6q writer=c kind=analysis created=2026-08-16T13:29:06-06:00 --><p>Missionary origin did not determine permanent ecclesiastical ownership. In Catholic communities a diocesan or missionary ordinary governed the local church entrusted to him, while a religious superior governed the members and internal life of an institute. An agreement could entrust a parish, school, clinic, or territory to an institute without making the institute the diocese. Protestant churches followed their own denominational and congregational orders; coexistence or practical cooperation did not create Catholic communion or approval of doctrine.</p><p>Japanese authorities could regulate civil incorporation, property, schools, visas, transport, public order, and security contacts. Those powers could sustain, constrain, or interrupt mission work, but they did not appoint a Catholic bishop, grant sacramental faculties, or decide Christian doctrine. Restrictions on foreign missionaries therefore did not by themselves dissolve a local church. Indigenous clergy, pastors, catechists, teachers, women's groups, choirs, elders, and families could preserve worship and records after an overseas society lost personnel or communication.</p><p>Claims of foreign political direction require instructions, funds, agents, or coordinated acts rather than the existence of communion or correspondence abroad. Shrine and imperial-observance disputes likewise turn on the required act, its official explanation, the judgment of the relevant church authority, and the practical freedom to abstain; the label <em>civic</em> did not settle every case. Canonical erection and assignment instruments, mission annals, personnel lists, parish and sacramental registers, school accounts, government surveillance files, correspondence, and oral histories are needed before reconstructing exact jurisdictions or compliance. The 1985 diocesan map, bishops, denominational rosters, and state agreements remain open.</p><!-- altwwii-writer-block:end -->"},
      {id:"language",title:"Language and literacy",html:"<p>Bible translation, hymns, sermons, prayer books, and schools created major written traditions in island languages. Japanese later displaced many languages from formal education without ending church use.</p>"},
      {id:"japanese",title:"Japanese religious policy",html:"<p>The naval and civilian governments monitored foreign missionaries and church connections while recognizing Christianity's social influence. Officials encouraged politically compliant mission work and restricted activity considered disloyal.</p>"},
      {id:"shinto",title:"Christianity and imperial rites",html:"<p>Schools and public ceremonies required participation in imperial observance. Christians debated whether shrine attendance was civic loyalty or religious compromise, producing different local accommodations.</p>"},
      {id:"war",title:"The long war",html:"<p>Military zones, shipping shortages, surveillance, evacuation, and suspicion of foreign clergy strained churches. Local leadership preserved congregations where outside missions lost contact.</p>"},
      {id:"society",title:"Churches and island society",html:"<p>Christian marriage, Sunday observance, temperance, schooling, and moral discipline coexist with clan, chiefly, land, food-exchange, and ancestral traditions. Conversion did not make island cultures uniform.</p>"},
      {id:"1985",title:"Christianity in 1985",html:"<p>By 1985 Catholic and Protestant churches remain major public institutions despite Japanese national dominance. They support indigenous languages and diaspora communities while usually avoiding a direct challenge to incorporation.</p>"}
    ],
    related:[{href:"education-japanese-micronesia.html",kicker:"Mission-school legacy",label:"Education in Japanese Micronesia"},{href:"japanese-language-micronesia.html",kicker:"Language competition",label:"Japanese Language in Micronesia"},{href:"kosraean-people.html",kicker:"Protestant island case",label:"Kosraean People"},{href:"chamorro-people.html",kicker:"Catholic island case",label:"Chamorro People"},{href:"marshallese-people.html",kicker:"Atoll church case",label:"Marshallese People"},{href:"micronesian-migration-diaspora.html",kicker:"Diaspora congregations",label:"Micronesian Migration and Diaspora"}],
    facts:[["Principal traditions","Roman Catholic and Protestant"],["Major Catholic heartland","Mariana Islands"],["Major Protestant heartlands","Kosrae, Ponape, and Marshall Islands"],["Principal local roles","Worship, literacy, welfare, funerals, music, and migration support"],["Japanese policy","Supervision, accommodation, and loyalty requirements"],["Language role","Translation and indigenous-language worship"],["Imperial tension","Shrine and civic-rite participation"],["1985 condition","Major island institution"]],
    sources:[{href:"https://www.jstage.jst.go.jp/article/shigaku/112/4/112_KJ00003652942/_article/-char/ja/",label:"Historical research — Japanese naval rule and religion in Micronesia"},{href:"https://micsem.org/pubs/articles/education/insearch.htm",label:"Micronesian Seminar — missions and colonial education"},{href:"https://www.spf.org/islandstudies/global-data/a00023.pdf",label:"Ocean Policy Research Institute — churches under Japanese rule"}]
  }),
  "education-japanese-micronesia":micronesianInstitutionArticle({
    title:"Education in Japanese Micronesia",eyebrow:"Colonial and regional education · Empire of Japan",infoboxKicker:"Japanese-language school system of the Pacific territories",
    lead:"Education in Japanese Micronesia developed from mission literacy into a Japanese public-school system beginning under naval rule in 1915. Colonial schools taught Japanese language, arithmetic, hygiene, manual and vocational work, loyalty, and limited academic subjects. Separate institutions and unequal curricula placed Micronesian children below metropolitan and settler pupils even as schooling created new routes into the empire.",
    canon:"Mission-school foundations, 1915 Japanese public system, language-centered moral education, segregated schools, unequal curricula, vocational emphasis, limited advancement, and district variation are historical. Postwar expansion, citizenship, technical access, and later preservation programs follow setting canon. Exact 1985 school names, enrollment, curriculum hours, examinations, and university routes remain open.",
    sections:[
      {id:"mission",title:"Mission schools",html:"<p>Catholic and Protestant missions introduced literacy, hymns, scripture, arithmetic, and teacher training in several island languages. Their reach varied sharply by island and denomination.</p>"},
      {id:"1915",title:"Japanese public schools",html:"<p>The naval government opened a territorial public-school system in 1915 and expanded it through the civil administration. Japanese language served as both the medium and the stated vehicle of moral transformation.</p>"},
      {id:"segregation",title:"Segregated education",html:"<p>Micronesian pupils and Japanese settler children generally attended different schools. Settler institutions offered fuller national curricula and easier paths into secondary education.</p>"},
      {id:"curriculum",title:"Curriculum",html:"<p>Island schools emphasized spoken Japanese, basic literacy, arithmetic, hygiene, agriculture, crafts, discipline, and practical work. Local language and history received inconsistent recognition.</p>"},
      {id:"mobility",title:"Mobility and limits",html:"<p>Fluent graduates entered clerical work, teaching, nursing, police assistance, company employment, shipping, and military service. Restricted secondary access preserved a racial and occupational hierarchy.</p>"},
      {id:"war",title:"Wartime schooling",html:"<p>Fortification, labor demands, shortages, evacuation, and military instruction disrupted education. Strategic islands experienced greater coercion and loss of ordinary school time.</p>"},
      {id:"postwar",title:"Postwar national system",html:"<p>Japanese victory makes island residents citizens and expands secondary, technical, teacher, and nursing education. Metropolitan standards remain dominant, and small islands depend on boarding or migration.</p>"},
      {id:"provisioning",title:"Provisioning an outer-island school",html:"<!-- altwwii-writer-block:start id=wb-v-20260816-m6r2x writer=v kind=extrapolation created=2026-08-16T12:21:02-06:00 --><p>On a small island, the school year depended upon the transport calendar. Teacher appointments, replacement staff, textbooks, examination papers, stationery, furniture parts, and equipment had to reach a landing place by scheduled ship or aircraft and then move through the local council, mission, or school store. A missed connection could leave a class sharing old books or following the subjects that the available teacher and materials could actually support.</p><p>Keeping a posted teacher required housing, pay access, leave and return passage, and workable arrangements for family life as well as a government appointment. Locally trained teachers and mission educators reduced dependence upon rotation from a district center, but they did not remove the credential and language advantages attached to metropolitan training. Boarding and migration consequently remained both remedies for thin local provision and causes of family and language separation.</p><!-- altwwii-writer-block:end -->"},
      {id:"1985",title:"Education in 1985",html:"<p>By 1985 Japanese is universal in public schooling, while local-language classes, cultural programs, church teaching, and community readers vary by district. Educational access improves more quickly than cultural equality.</p>"}
    ],
    related:[{href:"japanese-language-micronesia.html",kicker:"School language",label:"Japanese Language in Micronesia"},{href:"christianity-japanese-micronesia.html",kicker:"Mission foundation",label:"Christianity in Japanese Micronesia"},{href:"japanese-preservationism.html",kicker:"Later language policy",label:"Japanese Preservationism"},{href:"south-seas-mandate.html",kicker:"Colonial administration",label:"South Seas Mandate"},{href:"micronesian-migration-diaspora.html",kicker:"Student migration",label:"Micronesian Migration and Diaspora"},{href:"woleai-script.html",kicker:"Displaced writing tradition",label:"Woleai Script"}],
    facts:[["Public-system foundation","1915"],["Principal medium","Japanese"],["Earlier foundation","Catholic and Protestant mission schools"],["Colonial structure","Separate schools for islanders and settlers"],["Islander emphasis","Basic, moral, manual, and vocational education"],["Major barrier","Restricted secondary and professional access"],["Postwar status","National system with unequal regional access"],["1985 language support","Variable local-language and cultural programs"]],
    sources:[{href:"https://eric.ed.gov/?id=EJ218929",label:"Educational Perspectives — schooling under Japanese mandate rule"},{href:"https://micsem.org/article/schools-in-micronesia-prior-to-american-administration/",label:"Micronesian Seminar — schools before American administration"},{href:"https://www.spf.org/islandstudies/global-data/a00023.pdf",label:"Ocean Policy Research Institute — Japanese mandatory education"}]
  }),
  "japanese-language-micronesia":micronesianInstitutionArticle({
    title:"Japanese language in Micronesia",category:"Languages",eyebrow:"Japanese language · Pacific territories",infoboxKicker:"Public lingua franca of Japanese Micronesia",
    lead:"Japanese is the national language, principal school medium, and inter-island public lingua franca of Japanese Micronesia. It connects administration, military service, shipping, companies, secondary education, medicine, and mass media across territories with dozens of indigenous languages. Its usefulness is inseparable from the colonial hierarchy that displaced local languages from prestigious domains.",
    canon:"Japanese-language colonial schooling, administration, settler dominance, island loanwords, unequal bilingualism, and public-language pressure are historical. Continuous national-language status through 1985 follows setting canon. Exact regional dialects, proficiency, curriculum, legal status, media shares, and loanword inventories remain open.",
    sections:[
      {id:"arrival",title:"Colonial expansion",html:"<p>Naval administration after 1914 made Japanese necessary for official contact. Civil government, settlers, companies, schools, shipping, and military institutions expanded it into daily public life.</p>"},
      {id:"school",title:"School language",html:"<p>Japanese served as the medium of territorial public education and the route into further study. Children learned a language of national loyalty as well as practical communication.</p>"},
      {id:"lingua",title:"Inter-island lingua franca",html:"<p>Palauan, Chamorro, Yapese, Chuukic, Pohnpeic, Kosraean, Marshallese, and Polynesian speakers use Japanese when no indigenous language is shared. Ports and district centers intensify multilingual contact.</p>"},
      {id:"varieties",title:"Regional Japanese",html:"<p>Island speech incorporates local pronunciation, rhythm, vocabulary, particles, and code-switching. Settler communities preserve metropolitan and Okinawan varieties that also influence indigenous speakers.</p>"},
      {id:"loans",title:"Loanwords",html:"<p>Indigenous languages borrow terms for school, government, money, machines, medicine, transport, food, sport, military service, and household goods. Borrowing does not by itself prove language replacement.</p>"},
      {id:"inequality",title:"Unequal bilingualism",html:"<p>Micronesians must learn Japanese for advancement, while settlers can often live without learning an island language. Accent, vocabulary, and school background become markers of class and origin.</p>"},
      {id:"preservation",title:"Preservation-era policy",html:"<p>Local-language broadcasting, readers, dictionaries, cultural classes, and interpreter services expand in the later twentieth century. Japanese remains the unquestioned language of national institutions.</p>"},
      {id:"1985",title:"Position in 1985",html:"<p>By 1985 nearly every younger island resident has substantial Japanese ability, but proficiency and home use vary. Japanese unifies public life while accelerating the vulnerability of small languages and urban indigenous varieties.</p>"}
    ],
    related:[{href:"education-japanese-micronesia.html",kicker:"Primary transmission system",label:"Education in Japanese Micronesia"},{href:"micronesian-languages.html",kicker:"Indigenous language field",label:"Micronesian Languages"},{href:"japanese-preservationism.html",kicker:"Language policy",label:"Japanese Preservationism"},{href:"japanese-settlement-micronesia.html",kicker:"Settler expansion",label:"Japanese Settlement in Micronesia"},{href:"micronesian-migration-diaspora.html",kicker:"Mobility and language",label:"Micronesian Migration and Diaspora"},{href:"south-seas-mandate.html",kicker:"Colonial foundation",label:"South Seas Mandate"}],
    facts:[["Status","National and principal public language"],["Territorial expansion","After 1914"],["Primary transmission","Public schools"],["Major domains","Government, shipping, companies, military, medicine, and secondary education"],["Regional function","Inter-island lingua franca"],["Indigenous effect","Loanwords, bilingualism, and domain displacement"],["Structural inequality","Islanders need Japanese more than settlers need island languages"],["1985 position","Near-universal among younger residents"]],
    sources:[{href:"https://micsem.org/article/schools-in-micronesia-prior-to-american-administration/",label:"Micronesian Seminar — Japanese language and moral education"},{href:"https://eric.ed.gov/?id=EJ218929",label:"Educational Perspectives — language and segregation in mandate schools"},{href:"https://www.spf.org/islandstudies/global-data/a00023.pdf",label:"Ocean Policy Research Institute — Japanization under mandatory rule"}]
  }),
  "indigenous-government-japanese-micronesia":micronesianInstitutionArticle({
    title:"Indigenous government in Japanese Micronesia",eyebrow:"Customary authority and local administration · Empire of Japan",infoboxKicker:"Island political institutions under Japanese sovereignty",
    lead:"Indigenous government in Japanese Micronesia comprises the chiefs, titled houses, clans, lineages, village councils, island leaders, land authorities, and mediators that govern local relationships beneath Japanese sovereignty. Their structures differ fundamentally among Palau, Yap, Truk, Ponape, Kosrae, the Marshalls, the Marianas, and the outer islands.",
    canon:"Regional chiefly and lineage systems, Japanese use of local intermediaries, municipal and district administration, customary land authority, unequal colonial status, and institutional persistence are historical. Postwar citizenship and continued Japanese sovereignty follow setting canon. Exact 1985 councils, titles, appointment rules, jurisdictions, and election systems remain open.",
    sections:[
      {id:"diversity",title:"Political diversity",html:"<p>Palauan male and female titleholders, Yapese village estates, Pohnpeian Nahnmwarki orders, Marshallese iroij and land roles, Kosraean royal memory, Chamorro village institutions, and outer-atoll chiefs cannot be reduced to one model.</p>"},
      {id:"land",title:"Authority over land and sea",html:"<p>Customary leaders interpret descent, adoption, inheritance, boundaries, reef access, work, tribute, and compensation. Authority is strongest where relationships are maintained in daily life.</p>"},
      {id:"colonial",title:"Colonial intermediaries",html:"<p>German and Japanese officials recognize, appoint, supervise, bypass, or redefine local leaders according to administrative need. Written offices can strengthen one title while weakening rival or complementary authorities.</p>"},
      {id:"district",title:"District administration",html:"<p>Koror, Yap, Truk, Ponape, Saipan, and Jaluit connect island communities to police, courts, schools, health services, shipping, taxation, and public works. Remoteness determines how continuously the state is present.</p>"},
      {id:"representation",title:"Representation",html:"<p>Advisory councils and later territorial assemblies give islanders a voice within Japanese government. Small communities fear domination by settlers, district capitals, or larger indigenous populations.</p>"},
      {id:"citizenship",title:"Citizenship after victory",html:"<p>Permanent incorporation gives Micronesians national citizenship and formal access to Japanese law. It does not automatically transfer customary authority into the national constitution or eliminate administrative discrimination.</p>"},
      {id:"conflict",title:"Jurisdictional conflict",html:"<p>Land, adoption, marriage, fishing, inheritance, public order, and development can fall under both customary and Japanese institutions. Negotiated overlap is more common than a clean separation.</p>"},
      {id:"1985",title:"Government in 1985",html:"<p>By 1985 customary leaders remain influential in land, culture, ceremony, mediation, and community welfare. Japanese district and municipal institutions control budgets, criminal law, national policy, and most professional administration.</p>"}
    ],
    related:[{href:"land-tenure-japanese-micronesia.html",kicker:"Customary jurisdiction",label:"Land Tenure in Japanese Micronesia"},{href:"sawei-system.html",kicker:"Historic regional hierarchy",label:"Sawei"},{href:"palauan-people.html",kicker:"Title-system case",label:"Palauan People"},{href:"pohnpeian-people.html",kicker:"Nahnmwarki case",label:"Pohnpeian People"},{href:"marshallese-people.html",kicker:"Iroij and land-role case",label:"Marshallese People"},{href:"south-seas-mandate.html",kicker:"Colonial framework",label:"South Seas Mandate"}],
    facts:[["Scope","Chiefs, titles, clans, lineages, councils, and island leaders"],["Uniform regional system","None"],["Core customary fields","Land, reef, kinship, ceremony, mediation, and exchange"],["Colonial mechanism","Recognition and supervision through district government"],["District centers","Koror, Yap, Truk, Ponape, Saipan, and Jaluit"],["Postwar national status","Japanese citizenship"],["State-controlled fields","Budgets, criminal law, national policy, and professional administration"],["1985 condition","Persistent customary authority under Japanese sovereignty"]],
    sources:[{href:"https://www.palaugov.pw/who-we-are/",label:"Palau reference — titled and clan authority"},{href:"https://nach.gov.fm/nan-madol-east-site-of-temwen-island-temwen-island/",label:"FSM National Archives — Pohnpeian political history"},{href:"https://www.rmiembassyus.org/country-profile",label:"Marshall Islands reference — chiefly and land roles"}]
  }),
  "micronesian-migration-diaspora":micronesianInstitutionArticle({
    title:"Micronesian migration and diaspora",eyebrow:"Population movement · Japanese Micronesia",infoboxKicker:"Inter-island and imperial mobility",
    lead:"Micronesian migration and diaspora describe the movement of island peoples among atolls, district capitals, plantation islands, naval centers, and the Japanese home islands. Voyaging and marriage long predate colonial rule, while schools, companies, military service, medicine, storms, and wage work create new routes. Common Japanese nationality makes movement legally possible without making it equal or culturally neutral.",
    canon:"Precolonial voyaging, Carolinian migration to the Marianas, storm displacement, district-capital migration, Japanese labor and school movement, settler-majority centers, and diaspora language pressure are historical or direct setting consequences. Exact 1985 flows, residence law, census totals, neighborhoods, remittance volume, and return rates remain open.",
    sections:[
      {id:"precolonial",title:"Voyaging before colonial rule",html:"<p>Marriage, adoption, refuge, exchange, navigation teaching, warfare, disaster, and settlement moved people across the islands long before European administration. Island identity therefore never required complete immobility.</p>"},
      {id:"marianas",title:"Carolinian settlement of the Marianas",html:"<p>Nineteenth-century families from Satawal, Lamotrek, and neighboring atolls resettled Saipan and other northern islands. Their descendants formed the Refaluwasch people and Carolinian language.</p>"},
      {id:"capitals",title:"District capitals",html:"<p>Koror, Saipan, Truk, Ponape, and Jaluit attract students, patients, clerks, sailors, laborers, clergy, and families. Migrant neighborhoods reproduce island institutions while increasing intermarriage.</p>"},
      {id:"companies",title:"Company and military movement",html:"<p>Sugar estates, phosphate mines, fishing fleets, construction, ports, naval bases, and military service recruit islanders unevenly. Company sponsorship can determine housing, transport, and permission to relocate.</p>"},
      {id:"japan",title:"Migration to metropolitan Japan",html:"<p>Students, soldiers, nurses, seamen, technicians, athletes, entertainers, and company employees reach Okinawa and the home islands. Japanese fluency and sponsorship matter more than formal citizenship alone.</p>"},
      {id:"diaspora",title:"Diaspora institutions",html:"<p>Churches, island associations, language circles, funerals, remittances, food exchange, radio, and boarding houses sustain communities away from ancestral land. Concentrated settlement can preserve a language better than isolated households.</p>"},
      {id:"return",title:"Return and obligation",html:"<p>Migrants return for marriage, inheritance, funerals, chiefly events, retirement, storms, and cultural teaching. Rights in land and reef often depend on continued relationships rather than descent alone.</p>"},
      {id:"1985",title:"Migration in 1985",html:"<p>By 1985 Japanese Micronesia contains several overlapping diasporas rather than one assimilated island population. Mobility expands education and income while shifting children toward Japanese and weakening the resident base of remote islands.</p>"}
    ],
    related:[{href:"carolinian-people-marianas.html",kicker:"Historic settler diaspora",label:"Carolinian People of the Marianas"},{href:"japanese-settlement-micronesia.html",kicker:"Countervailing metropolitan migration",label:"Japanese Settlement in Micronesia"},{href:"japanese-language-micronesia.html",kicker:"Language of mobility",label:"Japanese Language in Micronesia"},{href:"education-japanese-micronesia.html",kicker:"Student movement",label:"Education in Japanese Micronesia"},{href:"land-tenure-japanese-micronesia.html",kicker:"Home-island rights",label:"Land Tenure in Japanese Micronesia"},{href:"koror.html",kicker:"Major migration center",label:"Koror"}],
    facts:[["Older causes","Marriage, refuge, exchange, navigation, conflict, and settlement"],["Colonial causes","Schools, companies, medicine, military service, and wage work"],["Major historic movement","Carolinian settlement of the northern Marianas"],["Principal district destinations","Koror, Saipan, Truk, Ponape, and Jaluit"],["Metropolitan destinations","Okinawa and Japanese home islands"],["Legal framework","Common Japanese nationality"],["Diaspora institutions","Churches, associations, language circles, remittances, and funerals"],["Major cultural pressure","Shift toward Japanese among migrant children"]],
    sources:[{href:"https://www.guampedia.com/pop-cultures-cnmi/",label:"Guampedia — Carolinian migration and northern-Mariana communities"},{href:"https://www.guampedia.com/carolinians-on-guam/",label:"Guampedia — storm migration and island networks"},{href:"https://en.wikipedia.org/wiki/Japanese_Micronesians",label:"Historical reference — migration and colonial hierarchy"}]
  })
});

